/* test_bus_layout.c: hold the C bus to the committed layout vectors.
 *
 * src/tests/fixtures/bus/layout_vectors.tsv is generated by
 * scripts/gen_bus_layout_vectors.py, which declares every region, ring, attach,
 * lease-view and AMOD layout from the specification, independently of any
 * implementation. This test checks the C structures and constants against it
 * in both directions: every row must match a C value, and every C value listed
 * here must have a row. The Go (server-go/bus/layout_test.go) and Rust
 * (rust/aimee-bus/src/layout.rs) clients are held to the same table, so the
 * three agree through it rather than by reading each other.
 *
 * Offsets come from offsetof on the shared structures. The AMOD envelope has no
 * C struct on the wire, so its offsets are checked by encoding a message with
 * distinct field values and finding each value at the table's offset.
 */
#include <errno.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <aimee/core/event_bus/bus_attach.h>
#include <aimee/core/event_bus/bus_region.h>
#include <aimee/core/event_bus/bus_ring.h>
#include <aimee/core/event_bus/bus_wire.h>
#include <aimee/core/event_bus/module_protocol.h>

#include "../core/event_bus/bus_region_internal.h"

#ifndef BUS_VECTOR_DIR
#define BUS_VECTOR_DIR "fixtures/bus"
#endif
#define LAYOUT_PATH BUS_VECTOR_DIR "/layout_vectors.tsv"

static int failures;

static void fail(const char *what, const char *name)
{
   fprintf(stderr, "FAIL: %s: %s\n", what, name);
   failures++;
}

typedef struct
{
   const char *name;
   unsigned long long value;
   int seen;
} entry_t;

/* AMOD field offsets, found from the C codec's behaviour rather than read from
 * a struct (the envelope has none on the wire). A field the encoder takes from
 * the message is located by encoding two messages that differ only in it and
 * finding the first byte that differs. A field the encoder fixes (magic,
 * version, header_len) or that must be zero (flags) is located by corrupting
 * one byte at a time and finding the first offset whose corruption the decoder
 * reports with that field's own error. */
static const aimee_module_message_t amod_base = {.operation = AIMEE_MODULE_OP_RESULT,
                                                 .status = AIMEE_MODULE_STATUS_OK,
                                                 .stage_id = 1,
                                                 .flags = 0,
                                                 .body_len = 0,
                                                 .deadline_ns = 0,
                                                 .trace_id = 0};

static unsigned long long amod_varied(void (*vary)(aimee_module_message_t *))
{
   uint8_t a[AIMEE_MODULE_MESSAGE_HEADER_LEN], b[AIMEE_MODULE_MESSAGE_HEADER_LEN];
   aimee_module_message_t m = amod_base;
   if (aimee_module_message_encode(&m, a, sizeof a) != sizeof a)
      return ~0ull;
   vary(&m);
   if (aimee_module_message_encode(&m, b, sizeof b) != sizeof b)
      return ~0ull;
   for (size_t i = 0; i < sizeof a; i++)
      if (a[i] != b[i])
         return i;
   return ~0ull;
}

static unsigned long long amod_refused(aimee_module_message_result_t why)
{
   uint8_t good[AIMEE_MODULE_MESSAGE_HEADER_LEN];
   aimee_module_message_t m = amod_base;
   if (aimee_module_message_encode(&m, good, sizeof good) != sizeof good)
      return ~0ull;
   for (size_t i = 0; i < sizeof good; i++)
   {
      uint8_t b[sizeof good];
      memcpy(b, good, sizeof b);
      b[i] ^= 0x80;
      aimee_module_message_t out;
      if (aimee_module_message_decode(b, sizeof b, &out) == why)
         return i;
   }
   return ~0ull;
}

static void v_op(aimee_module_message_t *m)
{
   m->operation = AIMEE_MODULE_OP_INVOKE;
}
static void v_status(aimee_module_message_t *m)
{
   m->status = AIMEE_MODULE_STATUS_INTERNAL;
}
static void v_stage(aimee_module_message_t *m)
{
   m->stage_id = 2;
}
static void v_body(aimee_module_message_t *m)
{
   m->body_len = 1;
}
static void v_deadline(aimee_module_message_t *m)
{
   m->deadline_ns = 1;
}
static void v_trace(aimee_module_message_t *m)
{
   m->trace_id = 1;
}

int main(void)
{
#define E(n, v) {n, (unsigned long long)(v), 0}
   entry_t want[] = {
       E("version.spec", BUS_SPEC_VERSION),
       E("version.layout", BUS_LAYOUT_VERSION),
       E("version.wire", BUS_WIRE_VERSION),
       E("version.amod", AIMEE_MODULE_MESSAGE_VERSION),
       E("frame.size", BUS_WIRE_HDR_LEN),
       E("frame.magic", BUS_WIRE_MAGIC),

       E("kind.attach_request", BUS_KIND_ATTACH_REQUEST),
       E("kind.attach_reply", BUS_KIND_ATTACH_REPLY),
       E("kind.error", BUS_KIND_ERROR),
       E("kind.capability_absent", BUS_KIND_CAPABILITY_ABSENT),
       E("kind.overflow", BUS_KIND_OVERFLOW),
       E("kind.producer_reaped", BUS_KIND_PRODUCER_REAPED),
       E("kind.epoch_change", BUS_KIND_EPOCH_CHANGE),
       E("kind.capability_denied", BUS_KIND_CAPABILITY_DENIED),
       E("kind.lease_release", BUS_KIND_LEASE_RELEASE),
       E("kind.module_base", BUS_KIND_MODULE_BASE),

       E("control.magic", BUS_CONTROL_MAGIC),
       E("control.size", sizeof(bus_control_t)),
       E("control.off.magic", offsetof(bus_control_t, magic)),
       E("control.off.spec_version", offsetof(bus_control_t, spec_version)),
       E("control.off.layout_version", offsetof(bus_control_t, layout_version)),
       E("control.off.flags", offsetof(bus_control_t, flags)),
       E("control.off.slot_size", offsetof(bus_control_t, slot_size)),
       E("control.off.inline_budget", offsetof(bus_control_t, inline_budget)),
       E("control.off.queue_capacity", offsetof(bus_control_t, queue_capacity)),
       E("control.off.lease_view_slots", offsetof(bus_control_t, lease_view_slots)),
       E("control.off.arena_size", offsetof(bus_control_t, arena_size)),
       E("control.off.host_epoch", offsetof(bus_control_t, host_epoch)),
       E("control.off.host_heartbeat", offsetof(bus_control_t, host_heartbeat)),
       E("control.off.lease_view_off", offsetof(bus_control_t, lease_view_off)),
       E("control.off.reserved1", offsetof(bus_control_t, reserved1)),
       E("control.flag.lease_view", BUS_CONTROL_F_LEASE_VIEW),

       E("lease_view.slots", BUS_LEASE_VIEW_SLOTS),
       E("lease_view.entry.size", sizeof(bus_lease_view_t)),
       E("lease_view.entry.off.generation", offsetof(bus_lease_view_t, generation)),
       E("lease_view.entry.off.len", offsetof(bus_lease_view_t, len)),
       E("lease_view.entry.off.offset", offsetof(bus_lease_view_t, offset)),
       E("lease_view.region_bytes", bus_control_bytes()),

       E("qpair.magic", BUS_QPAIR_MAGIC),
       E("qpair.size", sizeof(bus_qpair_hdr_t)),
       E("qpair.off.magic", offsetof(bus_qpair_hdr_t, magic)),
       E("qpair.off.slot_size", offsetof(bus_qpair_hdr_t, slot_size)),
       E("qpair.off.capacity", offsetof(bus_qpair_hdr_t, capacity)),
       E("qpair.off.data_credits", offsetof(bus_qpair_hdr_t, data_credits)),
       E("qpair.off.control_credits", offsetof(bus_qpair_hdr_t, control_credits)),
       E("qpair.off.control_lost", offsetof(bus_qpair_hdr_t, control_lost)),
       E("qpair.off.inbound_off", offsetof(bus_qpair_hdr_t, inbound_off)),
       E("qpair.off.outbound_off", offsetof(bus_qpair_hdr_t, outbound_off)),
       E("qpair.off.client_heartbeat", offsetof(bus_qpair_hdr_t, client_heartbeat)),
       E("qpair.off.reserved", offsetof(bus_qpair_hdr_t, reserved)),
       E("qpair.ring_align", bus_region_align64(1)),

       E("ring.magic", BUS_RING_MAGIC),
       E("ring.off.magic", offsetof(bus_ring_shared_t, magic)),
       E("ring.off.slot_size", offsetof(bus_ring_shared_t, slot_size)),
       E("ring.off.capacity", offsetof(bus_ring_shared_t, capacity)),
       E("ring.off.mask", offsetof(bus_ring_shared_t, mask)),
       E("ring.off.slots_off", offsetof(bus_ring_shared_t, slots_off)),
       E("ring.off.head", offsetof(bus_ring_shared_t, head)),
       E("ring.off.tail", offsetof(bus_ring_shared_t, tail)),
       E("ring.size", offsetof(bus_ring_shared_t, slots)),

       E("arena.magic", BUS_ARENA_MAGIC),
       E("arena.size", sizeof(bus_arena_hdr_t)),
       E("arena.off.magic", offsetof(bus_arena_hdr_t, magic)),
       E("arena.off.reserved", offsetof(bus_arena_hdr_t, reserved)),
       E("arena.off.size", offsetof(bus_arena_hdr_t, size)),

       E("attach_request.magic", BUS_ATTACH_REQ_MAGIC),
       E("attach_request.size", sizeof(bus_attach_request_t)),
       E("attach_request.off.magic", offsetof(bus_attach_request_t, magic)),
       E("attach_request.off.wire_version_min", offsetof(bus_attach_request_t, wire_version_min)),
       E("attach_request.off.wire_version_max", offsetof(bus_attach_request_t, wire_version_max)),
       E("attach_request.off.principal_class", offsetof(bus_attach_request_t, principal_class)),
       E("attach_request.off.principal_ref", offsetof(bus_attach_request_t, principal_ref)),
       E("attach_reply.magic", BUS_ATTACH_REPLY_MAGIC),
       E("attach_reply.size", sizeof(bus_attach_reply_t)),
       E("attach_reply.off.magic", offsetof(bus_attach_reply_t, magic)),
       E("attach_reply.off.status", offsetof(bus_attach_reply_t, status)),
       E("attach_reply.off.handle_id", offsetof(bus_attach_reply_t, handle_id)),
       E("attach_reply.off.wire_version", offsetof(bus_attach_reply_t, wire_version)),
       E("attach_reply.off.slot_size", offsetof(bus_attach_reply_t, slot_size)),
       E("attach_reply.off.inline_budget", offsetof(bus_attach_reply_t, inline_budget)),
       E("attach_reply.off.queue_capacity", offsetof(bus_attach_reply_t, queue_capacity)),
       E("attach_reply.off.reserved", offsetof(bus_attach_reply_t, reserved)),
       E("attach_reply.off.arena_size", offsetof(bus_attach_reply_t, arena_size)),
       E("attach_reply.off.host_epoch", offsetof(bus_attach_reply_t, host_epoch)),
       E("attach_status.ok", BUS_ATTACH_OK),
       E("attach_status.denied_policy", BUS_ATTACH_DENIED_POLICY),
       E("attach_status.denied_version", BUS_ATTACH_DENIED_VERSION),
       E("attach_status.denied_noslot", BUS_ATTACH_DENIED_NOSLOT),
       E("attach_status.protocol", BUS_ATTACH_PROTOCOL),
       E("attach.descriptors", BUS_ATTACH_FDS),
       E("attach.fd.control", BUS_ATTACH_FD_CONTROL),
       E("attach.fd.arena", BUS_ATTACH_FD_ARENA),
       E("attach.fd.qpair", BUS_ATTACH_FD_QPAIR),

       E("lease_release.size", BUS_LEASE_RELEASE_LEN),
       E("lease_release.off.lease_id", BUS_LEASE_RELEASE_OFF_LEASE),
       E("lease_release.off.generation", BUS_LEASE_RELEASE_OFF_GENERATION),

       E("amod.magic", AIMEE_MODULE_MESSAGE_MAGIC),
       E("amod.size", AIMEE_MODULE_MESSAGE_HEADER_LEN),
       E("amod.off.magic", amod_refused(AIMEE_MODULE_MESSAGE_ERR_MAGIC)),
       E("amod.off.version", amod_refused(AIMEE_MODULE_MESSAGE_ERR_VERSION)),
       E("amod.off.header_len", amod_refused(AIMEE_MODULE_MESSAGE_ERR_HEADER)),
       E("amod.off.operation", amod_varied(v_op)),
       E("amod.off.status", amod_varied(v_status)),
       E("amod.off.stage_id", amod_varied(v_stage)),
       E("amod.off.flags", amod_refused(AIMEE_MODULE_MESSAGE_ERR_FLAGS)),
       E("amod.off.body_len", amod_varied(v_body)),
       E("amod.off.deadline_ns", amod_varied(v_deadline)),
       E("amod.off.trace_id", amod_varied(v_trace)),
       E("amod.max_body", AIMEE_MODULE_MESSAGE_MAX_BODY),
       E("amod.op.invoke", AIMEE_MODULE_OP_INVOKE),
       E("amod.op.result", AIMEE_MODULE_OP_RESULT),
       E("amod.status.ok", AIMEE_MODULE_STATUS_OK),
       E("amod.status.capability_absent", AIMEE_MODULE_STATUS_CAPABILITY_ABSENT),
       E("amod.status.cancelled", AIMEE_MODULE_STATUS_CANCELLED),
       E("amod.status.deadline_exceeded", AIMEE_MODULE_STATUS_DEADLINE_EXCEEDED),
       E("amod.status.invalid_request", AIMEE_MODULE_STATUS_INVALID_REQUEST),
       E("amod.status.internal", AIMEE_MODULE_STATUS_INTERNAL),
   };
#undef E
   const size_t nwant = sizeof want / sizeof want[0];

   FILE *f = fopen(LAYOUT_PATH, "r");
   if (!f)
   {
      fprintf(stderr, "FAIL: open %s: %s\n", LAYOUT_PATH, strerror(errno));
      return 1;
   }
   char line[512];
   size_t rows = 0;
   while (fgets(line, sizeof line, f))
   {
      if (line[0] == '#' || line[0] == '\n')
         continue;
      char *tab = strchr(line, '\t');
      if (!tab)
      {
         fail("malformed row", line);
         continue;
      }
      *tab = '\0';
      char *end = NULL;
      unsigned long long v = strtoull(tab + 1, &end, 0);
      if (end == tab + 1 || (*end != '\n' && *end != '\0'))
      {
         fail("malformed value", line);
         continue;
      }
      rows++;
      size_t i = 0;
      for (; i < nwant; i++)
         if (strcmp(want[i].name, line) == 0)
            break;
      if (i == nwant)
      {
         fail("row has no C counterpart (add one to test_bus_layout.c)", line);
         continue;
      }
      if (want[i].seen)
         fail("duplicate row", line);
      want[i].seen = 1;
      if (want[i].value != v)
      {
         fprintf(stderr, "FAIL: %s: table %llu, C %llu\n", line, v, want[i].value);
         failures++;
      }
   }
   fclose(f);
   for (size_t i = 0; i < nwant; i++)
      if (!want[i].seen)
         fail("C value missing from the table", want[i].name);
   if (rows == 0)
      fail("no rows", LAYOUT_PATH);
   if (failures)
   {
      fprintf(stderr, "test_bus_layout: %d failure(s)\n", failures);
      return 1;
   }
   printf("test_bus_layout: OK (%zu rows agree with the C layout)\n", rows);
   return 0;
}
